class Rectangle {
public:
    int length, breadth;
};

class Rectangle {
public:
    int length, breadth;

    // overload the + operator
    // function takes a Rectangle object as parameter
    // and returns a Rectangle object
    Rectangle operator + (Rectangle r) {

        // create temporary Rectangle object
        Rectangle temp;

        // add length of this object and of r parameter
        // store the result in length variable of temp object
        temp.length = this->length + r.length;

        // add breadth of this object and of r parameter
        // store the result in breadth variable of temp object
        temp.breadth = this->breadth + r.breadth;

        // return the temporary object       
        return temp;
    }
};

